/** number -- accept a bounded unsigned decimal value with no trailing text. */
static int number(const char *s, uint32_t *out)
{
    char *end;
    unsigned long v;
    if (!s || *s < '0' || *s > '9') return -1;
    v = strtoul(s, &end, 10);
    if (*end || v > 100000u) return -1;
    *out = (uint32_t)v; return 0;
}
/** status -- take one protected session snapshot and print its counters. */
static void status(void)
{
    venc_status_t s;
    venc_get_status(&s);
    printf("running=%d size=%lux%lu qp=%lu gop=%lu pictures=%lu IDR=%lu P=%lu errors=%lu\r\n",
        s.running,(unsigned long)s.width,(unsigned long)s.height,(unsigned long)s.qp,
        (unsigned long)s.gop,(unsigned long)s.pictures,(unsigned long)s.idr_pictures,
        (unsigned long)s.p_pictures,(unsigned long)s.errors);
    printf("TS bytes=%lu datagrams=%lu drops=%lu backlog=%lu bit/s=%lu\r\n",
        (unsigned long)s.ts_bytes,(unsigned long)s.datagrams,(unsigned long)s.dropped_pictures,
        (unsigned long)s.backlog,(unsigned long)s.bit_rate_bps);
    printf("last stream stop waited %lu us for a picture in flight\r\n",(unsigned long)s.stop_drain_us);
}
/** cli_version -- show the linked firmware identity. */
int cli_version(const MenuCommandContext *c) { (void)c; printf("RTLNet Zybo Z7-20 " RTLNET_BUILD_ID "\r\n"); return 0; }
/** cli_ip -- show the network owner's address and identified PHY. */
int cli_ip(const MenuCommandContext *c) { (void)c; rtlnet_network_show(); return 0; }
/** cli_camera -- show capture-domain camera state and counters. */
int cli_camera(const MenuCommandContext *c)
{
    rtlnet_camera_state_t s;
    (void)c;
    rtlnet_camera_read_state(RTLNET_PLAT_CSI2_BASE, &s);
    printf("OV5640 mode=%s seen=%lu admitted=%lu\r\n",
        rtlnet_sensor_get_mode() ? "1080p15" : "720p30",
        (unsigned long)s.seen, (unsigned long)s.admitted);
    printf("receiver=rtlnet_csi2_rx; show rx for the lane status and counters\r\n");
    return 0;
}
/** cli_encoder -- report encoder state. */
int cli_encoder(const MenuCommandContext *c) { (void)c; status(); return 0; }
/** cli_stream -- report stream state. */
int cli_stream(const MenuCommandContext *c) { (void)c; status(); return 0; }
/** cli_qp -- validate and set constant quantization. */
int cli_qp(const MenuCommandContext *c) { uint32_t v; return number(c->argv[0],&v) ? -1 : venc_set_qp(v); }
/** cli_gop -- validate and set the IDR period. */
int cli_gop(const MenuCommandContext *c) { uint32_t v; return number(c->argv[0],&v) ? -1 : venc_set_gop(v); }
/** cli_bitrate -- validate and set the rate-control target. */
int cli_bitrate(const MenuCommandContext *c) { uint32_t v; return number(c->argv[0],&v) ? -1 : venc_set_bitrate(v); }
/** cli_stop -- abandon an in-flight picture and release its slot. */
int cli_stop(const MenuCommandContext *c) { (void)c; venc_stop(); return 0; }
/** cli_start -- parse an IPv4 unicast destination and start the real session. */
int cli_start(const MenuCommandContext *c)
{
    unsigned a,b,d,e; int consumed = 0; uint32_t port;
    if (sscanf(c->argv[0],"%u.%u.%u.%u%n",&a,&b,&d,&e,&consumed) != 4 ||
        c->argv[0][consumed] || a > 223u || !a || b > 255u || d > 255u || e > 255u ||
        number(c->argv[1],&port) || !port || port > 65535u) return -1;
    return venc_start((a<<24)|(b<<16)|(d<<8)|e,(uint16_t)port);
}
/** cli_mode -- change sensor/admission mode only while streaming is stopped. */
int cli_mode(const MenuCommandContext *c)
{
    venc_status_t s; unsigned mode;
    if (!strcmp(c->argv[0],"720p30")) mode=0;
    else if (!strcmp(c->argv[0],"1080p15")) mode=1;
    else return -1;
    venc_get_status(&s); if (s.running) return -1;
    return rtlnet_sensor_mode(mode);
}
/** cli_rx -- show the camera receiver state, counters and raw maxima. */
int cli_rx(const MenuCommandContext *c) { (void)c; return rtlnet_rx_show(); }
/** cli_rx_clear -- clear the receiver counters. */
int cli_rx_clear(const MenuCommandContext *c) { (void)c; return rtlnet_rx_clear(); }
/** cli_rx_taps -- set the input delay tap of both data lanes. */
int cli_rx_taps(const MenuCommandContext *c) { uint32_t a,b; return (number(c->argv[0],&a) || number(c->argv[1],&b)) ? -1 : rtlnet_rx_set_taps(a,b); }
/** cli_rx_wb -- set the white balance gains. */
int cli_rx_wb(const MenuCommandContext *c)
{
    uint32_t r,g,b;
    return (number(c->argv[0],&r) || number(c->argv[1],&g) || number(c->argv[2],&b)) ? -1 : rtlnet_rx_set_wb(r,g,b);
}
/** cli_rx_black -- set the black level. */
int cli_rx_black(const MenuCommandContext *c) { uint32_t v; return number(c->argv[0],&v) ? -1 : rtlnet_rx_set_black(v); }
/** cli_rx_phase -- set the Bayer phase. */
int cli_rx_phase(const MenuCommandContext *c) { uint32_t v; return number(c->argv[0],&v) ? -1 : rtlnet_rx_set_phase(v); }
/** cli_rx_gamma -- enable or disable the gamma curve. */
int cli_rx_gamma(const MenuCommandContext *c) { uint32_t v; return (number(c->argv[0],&v) || v > 1u) ? -1 : rtlnet_rx_set_gamma((int)v); }
/** cli_rx_geq -- enable or disable the green equalisation. */
int cli_rx_geq(const MenuCommandContext *c) { uint32_t v; return (number(c->argv[0],&v) || v > 1u) ? -1 : rtlnet_rx_set_geq((int)v); }
/** cli_rx_hl -- enable or disable the highlight clamp and set its level. */
int cli_rx_hl(const MenuCommandContext *c)
{
    uint32_t on, level;
    return (number(c->argv[0],&on) || on > 1u || number(c->argv[1],&level) || level > 1023u) ? -1 : rtlnet_rx_set_highlight((int)on, level);
}
/** cli_rx_bitrev -- select the deserializer bit order. */
int cli_rx_bitrev(const MenuCommandContext *c) { uint32_t v; return (number(c->argv[0],&v) || v > 1u) ? -1 : rtlnet_rx_set_bitrev((int)v); }
/** cli_rx_settle -- set the HS settle time. */
int cli_rx_settle(const MenuCommandContext *c) { uint32_t v; return number(c->argv[0],&v) ? -1 : rtlnet_rx_set_settle(v); }
